--[[
* PartyramaXI - everything MobDB knows about a monster, from LandSandBoat's data (2.8.0).
*
* pximobdata.lua is generated by the test kit's lsbgen_mob.py from LandSandBoat's data\ecosystems.yaml,
* data\zones\*\mobs.yaml, sql\item_basic.sql and sql\mob_spell_lists.sql (GPL v3). A monster is found by its server id
* (every spawn LandSandBoat lists, with that spawn's level), else by zone and name.
*
* Record: { K = resistances (see pxiweak), nm, aggro, link, truesight, charm, jobs, respawn, stype, detects = { sight,
*   hearing, scent, magic, lowhp, ability }, family, species, element, drops = { { ids, chance } }, steal = { ids },
*   spells = { ids }, lvmin, lvmax }
*
* The badge row (one more layer of the enemy bar): NM, Aggressive, Links, True sight / sound, how it detects you
* (sight, sound, scent, magic, low health, job abilities), Charmable, plus an optional line of text (jobs, level,
* respawn). Hover the row (or the weakness row) for the whole card.
--]]
local imgui = require('imgui')
local Draw  = require('pxidraw')
local Info  = require('pxiinfo')
local Fonts = require('pxifonts')

local M = {}
M.png = nil                  -- Png object for icons\mob\ (set by partyramaxi.lua)
M.res = nil                  -- function () -> Ashita resource manager (item and spell names)
M.load_error = nil

--------------------------------------------------------------------------- data
local D = nil                -- pximobdata, loaded on first use
local RA, RB, RL, RX, RY, RN = {}, {}, {}, {}, {}, 0
local TL = nil               -- template lines (strings), parsed into records on use
local TREC = {}              -- template line -> parsed template
local NAMES, SPELLS = nil, nil

local function load()
    if D ~= nil then return D ~= false end
    local ok, d = pcall(require, 'pximobdata')
    if not ok or type(d) ~= 'table' then D = false; M.load_error = tostring(d); return false end
    D = d
    local n = 0
    for a, b, l, x, y in (d.R or ''):gmatch('(%d+) (%d+) (%d+) (%d+) (%d+)') do
        n = n + 1
        RA[n], RB[n], RL[n], RX[n], RY[n] = tonumber(a), tonumber(b), tonumber(l), tonumber(x), tonumber(y)
    end
    RN = n
    TL = {}
    for line in (d.T or ''):gmatch('[^\n]+') do TL[#TL + 1] = line end
    return true
end
M.load = load
function M.kind_count() return load() and #D.K or 0 end
function M.template_count() return load() and #TL or 0 end
function M.range_count() load(); return RN end
function M.data() return load() and D or nil end

local function split(s, sep)
    local t = {}
    if s == nil or s == '' then return t end
    for part in (s .. sep):gmatch('(.-)' .. sep:gsub('%p', '%%%0')) do t[#t + 1] = part end
    return t
end
local function ids(s, sep)
    local t = {}
    for _, v in ipairs(split(s, sep)) do local n = tonumber(v); if n then t[#t + 1] = n end end
    return t
end

local function template(l)
    local t = TREC[l]
    if t ~= nil then return t end
    local f = split(TL[l] or '', '\t')
    local flags = f[2] or ''
    t = {
        K = D.K[tonumber(f[1]) or 0],
        nm = flags:find('N', 1, true) ~= nil, aggro = flags:find('A', 1, true) ~= nil, link = flags:find('L', 1, true) ~= nil,
        truesight = flags:find('T', 1, true) ~= nil, charm = flags:find('C', 1, true) ~= nil,
        jobs = (f[3] ~= '' and f[3]) or nil, respawn = tonumber(f[4]), stype = (f[5] ~= '' and f[5]) or nil,
        detects = {}, family = (f[7] ~= '' and f[7]) or nil, species = (f[8] ~= '' and f[8]) or nil,
        element = (f[9] ~= '' and f[9]) or nil, drops = {}, steal = ids(f[11], ','), spell_list = tonumber(f[12]),
    }
    for _, d in ipairs(split(f[6], ',')) do t.detects[d] = true end
    for _, dr in ipairs(split(f[10], ';')) do
        local list, chance = dr:match('^([^:]+):?(.*)$')
        if list then t.drops[#t.drops + 1] = { ids = ids(list, '/'), chance = chance } end
    end
    TREC[l] = t
    return t
end

local function spells_of(list)
    if list == nil then return nil end
    if SPELLS == nil then
        SPELLS = {}
        for k, v in (D.S or ''):gmatch('(%d+)=([%d,]+)') do SPELLS[tonumber(k)] = v end
    end
    local v = SPELLS[list]
    if type(v) == 'string' then v = ids(v, ','); SPELLS[list] = v end
    return v
end

local function by_id(sid)
    local lo, hi = 1, RN
    while lo <= hi do
        local mid = math.floor((lo + hi) / 2)
        if sid < RA[mid] then hi = mid - 1
        elseif sid > RB[mid] then lo = mid + 1
        else return RL[mid], RX[mid], RY[mid] end
    end
    return nil
end

local function by_name(sid, name)
    if NAMES == nil then
        NAMES = {}
        for key, l, x, y in (D.N or ''):gmatch('([^\n=]+)=(%d+) (%d+) (%d+)') do NAMES[key] = { tonumber(l), tonumber(x), tonumber(y) } end
    end
    local e = NAMES[('%d:%s'):format(math.floor(sid / 4096) % 4096, name:lower())]
    if e then return e[1], e[2], e[3] end
    return nil
end

-- The record for a monster (server id, name), or nil when LandSandBoat doesn't list it. One record per server id.
local CACHE = {}
function M.lookup(sid, name)
    if not load() or sid == nil or sid == 0 then return nil end
    local r = CACHE[sid]
    if r == nil then
        local l, x, y = by_id(sid)
        if l == nil and type(name) == 'string' then l, x, y = by_name(sid, name) end
        if l == nil then r = false
        else
            r = setmetatable({ lvmin = x, lvmax = y }, { __index = template(l) })
            r.spells = spells_of(r.spell_list)
        end
        CACHE[sid] = r
    end
    return r or nil
end
function M.forget() CACHE = {} end

--------------------------------------------------------------------------- text
local function res() local ok, r = pcall(M.res or function () return nil end); return ok and r or nil end
local function name_of(kind, id)
    local r = res()
    if r ~= nil then
        local ok, o = pcall(kind == 'item' and r.GetItemById or r.GetSpellById, r, id)
        if ok and o ~= nil then
            local n = o.Name
            if type(n) == 'table' or type(n) == 'userdata' then n = n[1] end
            if type(n) == 'string' and n ~= '' then return n end
        end
    end
    return ('%s #%d'):format(kind == 'item' and 'Item' or 'Spell', id)
end
M.name_of = name_of

local function dur(s)
    s = tonumber(s) or 0
    if s >= 86400 then local h = s / 3600; return (h % 1 == 0) and ('%d h'):format(h) or ('%.1f h'):format(h) end
    if s >= 3600 then local h, m = math.floor(s / 3600), math.floor(s % 3600 / 60); return m > 0 and ('%d h %d min'):format(h, m) or ('%d h'):format(h) end
    if s >= 60 then local m, x = math.floor(s / 60), s % 60; return x > 0 and ('%d min %d s'):format(m, x) or ('%d min'):format(m) end
    return ('%d s'):format(s)
end
M.dur = dur

function M.level_text(r)
    if r == nil or (r.lvmax or 0) <= 0 then return nil end
    local t = rawget(r, 'lvtext')
    if t then return t end
    if r.lvmin == r.lvmax or (r.lvmin or 0) <= 0 then t = ('Lv %d'):format(r.lvmax) else t = ('Lv %d-%d'):format(r.lvmin, r.lvmax) end
    rawset(r, 'lvtext', t)
    return t
end

local SENSES = { { 'sight', 'Sight' }, { 'hearing', 'Sound' }, { 'scent', 'Scent (tracks you)' }, { 'magic', 'Magic' },
    { 'lowhp', 'Low health' }, { 'ability', 'Job abilities' } }
M.SENSES = SENSES
local CHANCE = { always = 'always', very_common = 'very common', common = 'common', uncommon = 'uncommon', rare = 'rare',
    very_rare = 'very rare', super_rare = 'super rare', ultra_rare = 'ultra rare' }
local STYPE = { scripted = 'Placeholder / pop (scripted)', weather = 'In its weather', at_night = 'At night', at_evening = 'In the evening',
    fog = 'In fog', lottery = 'Lottery (placeholder)' }

-- The one-line summary drawn next to the badges: "WAR/BLM  Lv 10-12  5 min"
local SUMKEY = setmetatable({}, { __mode = 'k' })
function M.summary(r, cfg)
    local key = (cfg.show_jobs ~= false and 1 or 0) + (cfg.show_level and 2 or 0) + (cfg.show_respawn ~= false and 4 or 0)
    local c = SUMKEY[r]
    if c and c.key == key then return c.text end
    local t = {}
    if cfg.show_jobs ~= false and r.jobs then t[#t + 1] = r.jobs end
    if cfg.show_level and M.level_text(r) then t[#t + 1] = M.level_text(r) end
    if cfg.show_respawn ~= false and r.respawn then t[#t + 1] = dur(r.respawn) end
    local text = table.concat(t, '  ')
    SUMKEY[r] = { key = key, text = text }
    return text
end

-- The full card (tooltip). weak_text = the weaknesses in words (pxiweak), or nil.
local CARD = setmetatable({}, { __mode = 'k' })
function M.card(r, weak_text)
    local c = CARD[r]
    if c and c.w == weak_text then return c.text end
    local L = {}
    local fam = r.family
    if fam and r.species and r.species:sub(1, #fam) ~= fam then fam = fam .. ' (' .. r.species .. ')' end   -- 'Yagudo S' is just a Yagudo
    L[#L + 1] = (fam or 'Monster') .. (r.nm and '  -  Notorious Monster' or '')
    local lv = M.level_text(r)
    local a = {}
    if lv then a[#a + 1] = lv end
    if r.jobs then a[#a + 1] = 'Job ' .. r.jobs end
    if r.element then a[#a + 1] = 'Element ' .. r.element:sub(1, 1):upper() .. r.element:sub(2) end
    if #a > 0 then L[#L + 1] = table.concat(a, '   ') end
    L[#L + 1] = ('%s, %s%s%s'):format(r.aggro and 'Aggressive' or 'Passive', r.link and 'links' or 'does not link',
        r.truesight and ', true sight / sound (sees through Sneak and Invisible)' or '', r.charm and ', charmable' or '')
    local d = {}
    for _, s in ipairs(SENSES) do if r.detects[s[1]] then d[#d + 1] = s[2] end end
    L[#L + 1] = 'Detects by: ' .. (#d > 0 and table.concat(d, ', ') or 'nothing listed')
    if r.respawn then L[#L + 1] = 'Respawn: ' .. dur(r.respawn) end
    if r.stype then
        local s = {}
        for _, x in ipairs(split(r.stype, ',')) do s[#s + 1] = STYPE[x] or x end
        L[#L + 1] = 'Spawns: ' .. table.concat(s, ', ')
    end
    if weak_text and weak_text ~= '' then L[#L + 1] = ''; L[#L + 1] = weak_text end
    if #r.drops > 0 then
        L[#L + 1] = ''
        L[#L + 1] = 'Drops:'
        for i, dr in ipairs(r.drops) do
            if i > 14 then L[#L + 1] = ('  ... and %d more'):format(#r.drops - 14); break end
            local n = {}
            for j, id in ipairs(dr.ids) do
                if j > 4 then n[#n + 1] = '...'; break end
                n[#n + 1] = name_of('item', id)
            end
            L[#L + 1] = '  ' .. table.concat(n, ' / ') .. ((dr.chance ~= '' and (' (' .. (CHANCE[dr.chance] or dr.chance:gsub('_', ' ')) .. ')')) or '')
        end
    end
    if #r.steal > 0 then
        local n = {}
        for _, id in ipairs(r.steal) do n[#n + 1] = name_of('item', id) end
        L[#L + 1] = 'Steal: ' .. table.concat(n, ', ')
    end
    if r.spells and #r.spells > 0 then
        local n, seen = {}, {}
        for _, id in ipairs(r.spells) do
            local s = name_of('spell', id)
            if not seen[s] then seen[s] = true; n[#n + 1] = s end
        end
        local lines, cur = {}, 'Spells: '
        for i, s in ipairs(n) do
            local add = (i > 1 and ', ' or '') .. s
            if #cur + #add > 70 then lines[#lines + 1] = cur .. ','; cur = '  ' .. s else cur = cur .. add end
        end
        lines[#lines + 1] = cur
        for _, l in ipairs(lines) do L[#L + 1] = l end
    end
    L[#L + 1] = ''
    L[#L + 1] = '(LandSandBoat data; your server may differ.)'
    local text = table.concat(L, '\n')
    CARD[r] = { w = weak_text, text = text }
    return text
end

--------------------------------------------------------------------------- badges
-- { key, file, label, tile color, words }
local BADGES = {
    { 'nm', 'NM.png', 'NM', { 0.75, 0.60, 0.15, 0.95 }, 'Notorious Monster' },
    { 'aggro', 'Aggro.png', '!', { 0.70, 0.22, 0.20, 0.95 }, 'Aggressive' },
    { 'link', 'Link.png', 'Ln', { 0.75, 0.45, 0.15, 0.95 }, 'Links' },
    { 'truesight', 'TrueSight.png', 'TS', { 0.55, 0.30, 0.70, 0.95 }, 'True sight / sound' },
    { 'sight', 'Sight.png', 'Si', { 0.25, 0.28, 0.33, 0.95 }, 'Sight' },
    { 'hearing', 'Sound.png', 'So', { 0.25, 0.28, 0.33, 0.95 }, 'Sound' },
    { 'scent', 'Scent.png', 'Sc', { 0.25, 0.28, 0.33, 0.95 }, 'Scent' },
    { 'magic', 'Magic.png', 'Mg', { 0.25, 0.28, 0.33, 0.95 }, 'Magic' },
    { 'lowhp', 'LowHP.png', 'HP', { 0.25, 0.28, 0.33, 0.95 }, 'Low health' },
    { 'ability', 'Ability.png', 'JA', { 0.25, 0.28, 0.33, 0.95 }, 'Job abilities' },
    { 'charm', 'Charm.png', 'Ch', { 0.70, 0.30, 0.50, 0.95 }, 'Charmable' },
}
M.BADGES = BADGES
local SENSE = { sight = true, hearing = true, scent = true, magic = true, lowhp = true, ability = true }

-- Fills out with the badges cfg asks for; returns the count.
function M.build(r, cfg, out)
    local n = 0
    for _, b in ipairs(BADGES) do
        local k = b[1]
        local on
        if SENSE[k] then on = cfg.senses ~= false and r.detects[k] == true
        else on = cfg[k] ~= false and r[k] == true end
        if on then n = n + 1; out[n] = b end
    end
    for i = n + 1, #out do out[i] = nil end
    return n
end

local Q1, Q2, Q3, Q4 = { 0, 0 }, { 0, 0 }, { 0, 0 }, { 0, 0 }
local UV1, UV2, UV3, UV4 = { 0, 0 }, { 1, 0 }, { 1, 1 }, { 0, 1 }
local V1, V2 = { 0, 0 }, { 0, 0 }
local WHITE = { 1, 1, 1, 1 }
local function vec(v, x, y) v[1], v[2] = x, y; return v end

local function mouse()
    local ok, x, y = pcall(imgui.GetMousePos)
    if not ok then return nil end
    if type(x) == 'table' then x, y = x.x or x[1], x.y or x[2] end
    return tonumber(x), tonumber(y)
end
M.mouse = mouse

-- 2.9.0: the card is not an ImGui tooltip any more (the target bar is drawn on the foreground list, above every
-- window, so a tooltip ended up behind it). hover / show_text remember it; flush draws it last, on top of everything,
-- at the card text size.
local PEND = { on = false, text = nil, mx = 0, my = 0 }
function M.show_text(text)
    local mx, my = mouse()
    if text == nil or mx == nil then return end
    PEND.on, PEND.text, PEND.mx, PEND.my = true, text, mx, my
end
function M.pending() return PEND.on end
function M.pending_text() return PEND.on and PEND.text or nil end

-- Shows the card when the mouse is inside the rectangle.
function M.hover(r, x0, y0, x1, y1, weak_text)
    if r == nil or x0 == nil then return false end
    local mx, my = mouse()
    if mx ~= nil and mx >= x0 and mx <= x1 and my >= y0 and my <= y1 then
        M.show_text(M.card(r, weak_text))
        return true
    end
    return false
end

local LINES = setmetatable({}, { __mode = 'k' })
local CARD_BG, CARD_EDGE = { 0.06, 0.07, 0.10, 0.95 }, { 1, 1, 1, 0.22 }
local CARD_TITLE, CARD_HEAD, CARD_TEXT, CARD_NOTE = { 1.00, 0.84, 0.40, 1 }, { 0.62, 0.82, 1.00, 1 }, { 0.92, 0.92, 0.94, 1 }, { 0.62, 0.62, 0.66, 1 }
local CV1, CV2 = { 0, 0 }, { 0, 0 }
function M.flush(dl, push, scale, sw, sh)
    if not PEND.on then return end
    PEND.on = false
    local text = PEND.text
    if dl == nil or type(text) ~= 'string' then return end
    local base = (tonumber(imgui.GetFontSize and imgui.GetFontSize()) or 14)
    local p = push and push(scale or 1) or false
    local lh = (Info.text_size and select(2, Info.text_size('Ag'))) or base * (scale or 1)
    if lh <= 0 then lh = base * (scale or 1) end
    local key = text .. '\0' .. tostring(scale)
    local L = LINES[key]
    if L == nil then
        L = { w = 0 }
        for line in (text .. '\n'):gmatch('(.-)\n') do
            local w = (line ~= '' and Info.text_size) and Info.text_size(line) or 0
            L[#L + 1] = line
            if w > L.w then L.w = w end
        end
        LINES[key] = L
    end
    local pad = math.floor(8 * (scale or 1) + 0.5)
    local bw, bh = L.w + pad * 2, #L * lh + pad * 2
    local x, y = PEND.mx + 18, PEND.my + 18
    sw, sh = tonumber(sw) or 0, tonumber(sh) or 0
    if sw > 0 and x + bw > sw - 4 then x = math.max(4, PEND.mx - 12 - bw) end
    if sh > 0 and y + bh > sh - 4 then y = math.max(4, sh - 4 - bh) end
    CV1[1], CV1[2], CV2[1], CV2[2] = x, y, x + bw, y + bh
    dl:AddRectFilled(CV1, CV2, Draw.u32(CARD_BG, 1), 6)
    dl:AddRect(CV1, CV2, Draw.u32(CARD_EDGE, 1), 6)
    for i, line in ipairs(L) do
        if line ~= '' then
            local c = CARD_TEXT
            if i == 1 then c = CARD_TITLE
            elseif line:sub(-1) == ':' or line:match('^[%a ]+:$') then c = CARD_HEAD
            elseif line:sub(1, 1) == '(' then c = CARD_NOTE end
            CV1[1], CV1[2] = x + pad, y + pad + (i - 1) * lh
            dl:AddText(CV1, Draw.u32(c, 1), line)
        end
    end
    if p then Fonts.pop() end
end

-- Draws the badges (and the summary text after them) on one row around (x + dx, y + dy). Returns its rectangle.
function M.draw(dl, cfg, x, y, list, n, r, alpha, gx, gy, push, base, weak_text)
    if alpha <= 0.01 then return end
    local s = tonumber(cfg.size) or 16
    local gap = tonumber(cfg.spacing) or 2
    local txt = (cfg.text ~= false) and M.summary(r, cfg) or ''
    local p = (txt ~= '') and push and push(base * (tonumber(cfg.text_scale) or 0.8)) or false
    local tw = 0
    if txt ~= '' then tw = Info.text_size and Info.text_size(txt) or (#txt * 6) end
    local w = n * s + math.max(0, n - 1) * gap + ((txt ~= '' and n > 0) and 6 or 0) + tw
    if w <= 0 then if p then Fonts.pop() end return end
    local left = x + (tonumber(cfg.dx) or 0) + (gx or 0)
    if cfg.align == 'center' or cfg.align == nil then left = left - w / 2 elseif cfg.align == 'right' then left = left - w end
    left = math.floor(left + 0.5)
    local y0 = math.floor(y + (tonumber(cfg.dy) or 0) + (gy or 0) - s / 2 + 0.5)
    for i = 1, n do
        local b = list[i]
        local x0 = left + (i - 1) * (s + gap)
        local t = M.png and M.png:has(b[2]) and M.png:get(b[2]) or nil
        if t ~= nil and t.id ~= nil then
            Q1[1], Q1[2], Q2[1], Q2[2], Q3[1], Q3[2], Q4[1], Q4[2] = x0, y0, x0 + s, y0, x0 + s, y0 + s, x0, y0 + s
            dl:AddImageQuad(t.id, Q1, Q2, Q3, Q4, UV1, UV2, UV3, UV4, Draw.u32(WHITE, alpha))
        else
            dl:AddRectFilled(vec(V1, x0, y0), vec(V2, x0 + s, y0 + s), Draw.u32(b[4], alpha), 3)
            local pp = push and push(base * math.max(0.4, s / 34)) or false
            Info.text_at(dl, b[3], x0 + s / 2, y0 + s / 2, 'center', Draw.u32(WHITE, alpha), Info.ST)
            if pp then Fonts.pop() end
        end
    end
    if txt ~= '' then
        local tx = left + n * s + math.max(0, n - 1) * gap + (n > 0 and 6 or 0)
        Info.text_at(dl, txt, tx, y0 + s / 2, 'left', Draw.u32(cfg.text_color or WHITE, alpha), Info.ST)
    end
    if p then Fonts.pop() end
    local x1, y1 = left + w, y0 + s
    Draw.hl_rect('info', 'mob', left, y0, x1, y1)
    if cfg.tooltip ~= false then M.hover(r, left, y0, x1, y1, weak_text) end
    return left, y0, x1, y1
end

return M
